/**
 * print-fonts.ts — open fonts embedded into PDF/A print output.
 *
 * PDF/A (ISO 19005) forbids referencing a font that is not embedded in the file.
 * Our PDFs are produced by Chrome (Puppeteer `page.pdf()`) rendering the HTML
 * from `renderPrint`; the default body stack is system serif (Georgia / Times),
 * which a headless Linux box does NOT have — so Chrome substitutes a system font
 * and may reference it WITHOUT embedding it. The fix lives in the render path,
 * not the post-processor: serve open fonts via `@font-face` (as self-contained
 * `data:` URIs) so Chrome subsets and EMBEDS them into every PDF (finding
 * #27/#28 / G-07).
 *
 * The faces below are SUBSETS of Google's Noto family (SIL Open Font License 1.1):
 *   • Noto Serif (Latin + punctuation + currency)     → 'IT Serif'  (400/700)
 *   • Noto Naskh Arabic (Arabic, with GSUB/GPOS shaping) → 'IT Naskh' (400/700)
 *   • Noto Sans Mono (code blocks)                     → 'IT Mono'   (400)
 *   • Noto Sans Symbols 2 (ballot boxes ☐☑, bullets, ✓) → 'IT Symbols'
 * Subsetted with fontTools to keep the payload ~290 KB (woff2). Regenerate with
 * scripts/build-print-fonts (see that script for the exact unicode ranges).
 *
 * OFL requires the license to travel with the fonts: see `resources/OFL.txt`.
 * These bytes are emitted ONLY when `renderPrint(doc, { embedFonts: true })` —
 * the default print/HTML path stays lean.
 */

/* eslint-disable */
/* prettier-ignore-start */

const SERIF_R =
  "";
const SERIF_B =
  "";
const NASKH_R =
  "";
const NASKH_B =
  "";
const MONO_R =
  "";
const SYMBOLS =
  "";

function face(family: string, weight: number, b64: string): string {
  return (
    "@font-face{font-family:'" +
    family +
    "';font-style:normal;font-weight:" +
    weight +
    // A data: URI is available immediately (no network); no font-display needed.
    ";src:url(data:font/woff2;base64," +
    b64 +
    ") format('woff2');}"
  );
}

/**
 * The `@font-face` declarations plus the family overrides that force every print
 * surface onto an embedded face, so Chrome leaves NO glyph referencing a
 * non-embedded system font. Emitted after the theme CSS so it wins by source
 * order. Body → serif+arabic+symbols; code → mono; SVG seal/trust-band text
 * (authored sans-serif) → remapped to the embedded serif.
 */
export function printFontFaceCSS(): string {
  return [
    face("IT Serif", 400, SERIF_R),
    face("IT Serif", 700, SERIF_B),
    face("IT Naskh", 400, NASKH_R),
    face("IT Naskh", 700, NASKH_B),
    face("IT Mono", 400, MONO_R),
    face("IT Symbols", 400, SYMBOLS),
    // Force EVERY print surface onto an embedded face with !important + a scoped
    // universal selector, so a theme's own font-family (often set on headings with
    // higher specificity) can't leave a glyph pointing at a non-embedded system
    // font. Code elements keep the embedded monospace; SVG seal text (authored
    // sans-serif) is remapped to the embedded serif. This is intentional for
    // archival output — non-embedded fonts are exactly what PDF/A forbids.
    "html,body,body.it-print,.intent-document,.intent-document *:not(code):not(pre):not(kbd):not(samp){font-family:'IT Serif','IT Naskh','IT Symbols',Georgia,'Times New Roman',serif !important;}",
    ".intent-document code,.intent-document pre,.intent-document kbd,.intent-document samp,.intent-code code,pre,code,kbd,samp{font-family:'IT Mono','IT Symbols',monospace !important;}",
    "svg text{font-family:'IT Serif','IT Naskh',sans-serif !important;}",
    "@page{font-family:'IT Serif','IT Naskh','IT Symbols',serif;}",
  ].join("\n");
}
/* prettier-ignore-end */
